internal sealed class ThreadStatusJsonConverter : JsonConverter<ThreadStatus>
{
    public override ThreadStatus? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        if (reader.TokenType == JsonTokenType.Null) return null;
        var obj = JsonNode.Parse(ref reader) as JsonObject ?? throw new JsonException("ThreadStatus must be a JSON object.");
        var tag = AcpJson.GetTag(obj, "type");
        return tag switch
        {
            "notLoaded" => obj.Deserialize(CodexJsonContext.Default.NotLoadedThreadStatus),
            "idle" => obj.Deserialize(CodexJsonContext.Default.IdleThreadStatus),
            "systemError" => obj.Deserialize(CodexJsonContext.Default.SystemErrorThreadStatus),
            "active" => obj.Deserialize(CodexJsonContext.Default.ActiveThreadStatus),
            _ => new ThreadStatus.Unknown(tag, obj),
        };
    }

    public override void Write(Utf8JsonWriter writer, ThreadStatus value, JsonSerializerOptions options)
    {
        JsonNode? body = value switch
        {
            ThreadStatus.Unknown u => u.Raw,
            NotLoadedThreadStatus x => JsonSerializer.SerializeToNode(x, CodexJsonContext.Default.NotLoadedThreadStatus),
            IdleThreadStatus x => JsonSerializer.SerializeToNode(x, CodexJsonContext.Default.IdleThreadStatus),
            SystemErrorThreadStatus x => JsonSerializer.SerializeToNode(x, CodexJsonContext.Default.SystemErrorThreadStatus),
            ActiveThreadStatus x => JsonSerializer.SerializeToNode(x, CodexJsonContext.Default.ActiveThreadStatus),
            _ => throw new JsonException($"Unsupported ThreadStatus variant {value.GetType()}."),
        };
        AcpJson.WriteTagged(writer, "type", value is ThreadStatus.Unknown ? null : value.Tag, body);
    }
}

